#!/usr/bin/env python3
"""Shared local/CI checks. Generated by project setup; Python 3.11+."""

import argparse
import json
import os
import shutil
from pathlib import Path
import subprocess
import sys
import tomllib
import urllib.request

ROOT = Path(__file__).resolve().parent.parent
CONFIG = json.loads((ROOT / ".setup/checks.json").read_text())
TOOLS = {
    "google-java-format-1.24.0.jar": "https://github.com/google/google-java-format/releases/download/v1.24.0/google-java-format-1.24.0-all-deps.jar",
    "checkstyle-10.20.2.jar": "https://github.com/checkstyle/checkstyle/releases/download/checkstyle-10.20.2/checkstyle-10.20.2-all.jar",
}


def run(*command):
    print("+", " ".join(command), flush=True)
    subprocess.run(command, cwd=ROOT, check=True)


def java_sources():
    excluded = {".git", ".setup", "build", "target", ".gradle"}
    return [
        str(p.relative_to(ROOT))
        for p in sorted(ROOT.rglob("*.java"))
        if not excluded.intersection(p.relative_to(ROOT).parts)
    ]


def java_jar(name):
    path = ROOT / ".setup/tools" / name
    if not path.is_file():
        raise ValueError("Missing Java check tool. Run: python3 .setup/check.py tools")
    return str(path)


def java_build(*args):
    if CONFIG["java_build"] == "maven":
        wrapper = ROOT / "mvnw"
        run(*(["sh", "./mvnw"] if wrapper.exists() else ["mvn"]), "-B", *args)
    else:
        wrapper = ROOT / "gradlew"
        run(
            *(["sh", "./gradlew"] if wrapper.exists() else ["gradle"]),
            "--no-daemon",
            *args,
        )


def check(language, action):
    if language == "go":
        if action in ("format", "format-check"):
            paths = []
            for directory, dirs, files in os.walk(ROOT):
                dirs[:] = [
                    d for d in dirs if d not in {".git", "vendor", ".setup", ".venv"}
                ]
                paths += [
                    str(Path(directory, f).relative_to(ROOT))
                    for f in files
                    if f.endswith(".go")
                ]
            # Batch to avoid exceeding argv limits in larger projects.
            for offset in range(0, len(paths), 100):
                command = [
                    "gofmt",
                    "-w" if action == "format" else "-l",
                    *paths[offset : offset + 100],
                ]
                result = subprocess.run(
                    command, cwd=ROOT, check=True, capture_output=True, text=True
                )
                if action == "format-check" and result.stdout:
                    raise ValueError("Run format for:\n" + result.stdout)
        else:
            patterns = ["./..."]
            if (ROOT / "go.work").exists():
                workspace = subprocess.check_output(
                    ["go", "work", "edit", "-json"], cwd=ROOT, text=True
                )
                patterns = []
                for module in json.loads(workspace).get("Use", []):
                    path = (ROOT / module["DiskPath"]).resolve()
                    if not path.is_relative_to(ROOT):
                        raise ValueError(
                            "Workspace module outside project: " + str(path)
                        )
                    relative = path.relative_to(ROOT).as_posix()
                    patterns.append("./" + relative + "/...")
                if not patterns:
                    raise ValueError("Go workspace has no modules")
            if action == "lint":
                if not shutil.which("golangci-lint"):
                    raise ValueError(
                        "Missing golangci-lint v2. Install v2.13.2 from the official releases and add it to PATH (see README)."
                    )
                config = CONFIG.get("golangci_config", ".golangci.yml")
                for pattern in patterns:
                    run("golangci-lint", "run", "--config", config, pattern)
                return
            for pattern in patterns:
                run(
                    "go",
                    {"test": "test", "build": "build"}[action],
                    pattern,
                )
    elif language == "python":
        config = (
            ["--config", CONFIG["ruff_config"]] if CONFIG.get("ruff_config") else []
        )
        config += ["--exclude", ".setup"]
        if action == "format":
            run(sys.executable, "-m", "ruff", "format", *config, ".")
        elif action == "format-check":
            run(sys.executable, "-m", "ruff", "format", "--check", *config, ".")
        elif action == "lint":
            run(sys.executable, "-m", "ruff", "check", *config, ".")
        elif action == "test":
            run(sys.executable, "-m", "pytest")
        elif python_package():
            run(sys.executable, "-m", "build")
        else:
            print("Python build skipped: no package metadata")
    else:
        if action in ("format", "format-check", "lint"):
            paths = java_sources()
            for offset in range(0, len(paths), 100):
                batch = paths[offset : offset + 100]
                if action == "lint":
                    run(
                        "java",
                        "-jar",
                        java_jar("checkstyle-10.20.2.jar"),
                        "-c",
                        ".setup/checkstyle.xml",
                        *batch,
                    )
                else:
                    flags = (
                        ["--replace"]
                        if action == "format"
                        else ["--dry-run", "--set-exit-if-changed"]
                    )
                    run(
                        "java",
                        "-jar",
                        java_jar("google-java-format-1.24.0.jar"),
                        *flags,
                        *batch,
                    )
        elif action == "test":
            java_build("test")
        elif CONFIG["java_build"] == "maven":
            java_build("-DskipTests", "package")
        else:
            java_build("assemble")


def python_package():
    if (ROOT / "setup.py").exists():
        return True
    path = ROOT / "pyproject.toml"
    data = tomllib.loads(path.read_text()) if path.exists() else {}
    return "project" in data or "build-system" in data


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "action",
        choices=[
            "format",
            "format-check",
            "lint",
            "test",
            "build",
            "check",
            "tools",
            "deps",
        ],
    )
    parser.add_argument("--language", choices=CONFIG["languages"])
    args = parser.parse_args()
    if args.action == "deps":
        if "python" not in CONFIG["languages"]:
            raise ValueError("deps is only needed for Python")
        for command in CONFIG["python_install"]:
            run(
                *(
                    [sys.executable, *command[1:]]
                    if command[0] == "python3"
                    else command
                )
            )
        run(
            sys.executable,
            "-m",
            "pip",
            "install",
            "ruff==0.8.6",
            "pytest==8.3.4",
            "build==1.2.2.post1",
        )
        return
    if args.action == "tools":
        if "java" not in CONFIG["languages"]:
            raise ValueError("tools is only needed for Java")
        for name, url in TOOLS.items():
            path = ROOT / ".setup/tools" / name
            if not path.exists():
                path.parent.mkdir(parents=True, exist_ok=True)
                temporary = path.with_suffix(".download")
                try:
                    urllib.request.urlretrieve(url, temporary)
                    temporary.replace(path)
                finally:
                    temporary.unlink(missing_ok=True)
        return
    languages = [args.language] if args.language else CONFIG["languages"]
    actions = (
        ["format-check", "lint", "test", "build"]
        if args.action == "check"
        else [args.action]
    )
    for language in languages:
        for action in actions:
            check(language, action)


if __name__ == "__main__":
    try:
        main()
    except (ValueError, OSError, subprocess.CalledProcessError) as error:
        print(str(error), file=sys.stderr)
        sys.exit(1)
